import{F as e,_ as t,f as n,h as r,j as i,n as a}from"./chunks/shared.rYHlazZf.js";var o=JSON.parse(`{"title":"Adapte receitas práticas de automação","description":"","frontmatter":{"title":"Adapte receitas práticas de automação","docId":"user.automations.recipes","translationKey":"user.automations.recipes","locale":"pt","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"965a59a41c6330f1329be6e35858a2984a01be9515d373ed184b0c4ae8be2f23","translationRevision":"8420e1fc351c522562291e8812f7573ca5b90ebde73cd692f191c25738d383de","order":30},"headers":[],"relativePath":"pt/user/automations/recipes.md","filePath":"pt/user/automations/recipes.md","lastUpdated":1795731074000}`),s={name:`pt/user/automations/recipes.md`};function c(a,o,s,c,l,u){let d=e(`DemoFrame`);return i(),n(`div`,null,[o[0]||=r(`<h1 id="adapt-practical-automation-recipes" tabindex="-1">Adapte receitas práticas de automação <a class="header-anchor" href="#adapt-practical-automation-recipes" aria-label="Permalink to “Adapte receitas práticas de automação”">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo e pré-requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to “Objetivo e pré-requisitos”">​</a></h2><p>Transforme uma <a href="./first-rule.html">regra de registro</a> funcional em reações com correspondência restrita. Você precisa de um perfil ativo e de campos de evento observados. Comece com ações <code>core.log</code>; substitua-as por outro efeito somente após confirmar a correspondência e a frequência.</p><h2 id="match-a-chat-command" tabindex="-1">Reconheça um comando de chat <a class="header-anchor" href="#match-a-chat-command" aria-label="Permalink to “Reconheça um comando de chat”">​</a></h2><p>Crie um evento <code>tiktok.chat</code> com <code>event.data.comment</code> igual (<code>eq</code>) a <code>!hello</code>. Registre:</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Olá {{ event.user.uniqueId }}</span></span></code></pre></div><p>Use um intervalo de espera por usuário de <code>30</code> segundos para que um espectador não o acione continuamente, enquanto outro ainda tenha uma oportunidade independente. A igualdade exata é útil para comandos; a correspondência por conteúdo também aceita mensagens com texto ao redor. Escolha de forma consciente.</p><h2 id="record-a-qualifying-gift" tabindex="-1">Registre um presente que atenda aos critérios <a class="header-anchor" href="#record-a-qualifying-gift" aria-label="Permalink to “Registre um presente que atenda aos critérios”">​</a></h2><p>Crie um evento <code>tiktok.gift</code> com <code>event.data.diamondCount</code> maior ou igual (<code>gte</code>) a <code>10</code>. Registre:</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Presente {{ event.data.giftName }} de {{ event.user.uniqueId }}</span></span></code></pre></div><p>Inspecione primeiro os detalhes reais do presente. O valor em diamantes, a contagem de repetições e o indicador de conclusão são campos diferentes. Se quiser uma reação apenas na conclusão, verifique se os dados recebidos fornecem <code>event.data.repeatEnd</code> e use a condição booleana verdadeira. Não deduza uma execução por combo concluído apenas de um filtro de nome.</p><h2 id="bound-a-shared-reaction" tabindex="-1">Limite uma reação compartilhada <a class="header-anchor" href="#bound-a-shared-reaction" aria-label="Permalink to “Limite uma reação compartilhada”">​</a></h2><p>Crie um evento <code>tiktok.follow</code> com intervalo de espera global de <code>10</code> segundos. Vincule uma ação curta de registro. Se dois espectadores seguirem durante esse intervalo, a espera global pode suprimir a reação posterior. Use o escopo por usuário quando cada espectador precisar de uma permissão separada.</p><p>Para várias ações, ordene a lista e mantenha o modo de todas as ações quando cada etapa for necessária. O modo aleatório escolhe uma ação; não executa todas as etapas em ordem aleatória. Adicione <code>core.delay</code> apenas quando as etapas seguintes precisarem aguardar.</p><h2 id="expected-result-and-status" tabindex="-1">Resultado esperado e status <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to “Resultado esperado e status”">​</a></h2><p>Esses acionadores, filtros de campo e controles de espera estão disponíveis no mecanismo local. Uma execução deve corresponder a um evento aceito que atenda aos critérios, respeitando a espera e o estado de ativação. A aceitação específica do provedor ainda exige uma verificação na sua LIVE real.</p><h2 id="recovery" tabindex="-1">Recuperação <a class="header-anchor" href="#recovery" aria-label="Permalink to “Recuperação”">​</a></h2><p>Se uma receita falhar, volte a uma única ação de registro, inspecione os dados e simplifique temporariamente as condições. Não desative os limites de uma transmissão movimentada durante a investigação. Testes de áudio, pontos, HTTP e plugins podem produzir efeitos reais. Confira a <a href="./../plugins/audio.html">configuração de áudio</a>, as <a href="./variables.html">variáveis</a> e os <a href="./../preferences/troubleshooting.html">diagnósticos de execução</a> antes de adicionar essas dependências.</p><p>Experimente interativamente antes de tocar na sua configuração real:</p>`,19),t(d,{scenario:`automation`,locale:`pt`,panel:`automation`,title:`Experimente o espaço de automações`})])}var l=a(s,[[`render`,c]]);export{o as __pageData,l as default};